"""
Pydantic schemas for AI Resume Analysis and ATS evaluation.
"""

from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field


class AIResumeSkillItem(BaseModel):
    """Extracted skill item from LLM JSON output."""

    name: str
    category: str = "technical"  # "technical", "soft", "tool", "framework"
    proficiency: str | None = None


class AIResumeAnalysisPayload(BaseModel):
    """Schema to validate JSON response generated by Ollama."""

    structure_score: float = Field(..., ge=0, le=100, description="Structure & section completeness score (0-100)")
    skills_score: float = Field(..., ge=0, le=100, description="Skills & keywords density score (0-100)")
    experience_score: float = Field(..., ge=0, le=100, description="Work experience & impact score (0-100)")
    education_score: float = Field(..., ge=0, le=100, description="Education & certifications score (0-100)")
    formatting_score: float = Field(..., ge=0, le=100, description="Formatting & readability score (0-100)")

    skills: list[AIResumeSkillItem] = Field(default_factory=list)
    experience_summary: str = ""
    education_summary: str = ""
    project_summary: str = ""
    certifications: list[str] = Field(default_factory=list)
    strengths: list[str] = Field(default_factory=list)
    weaknesses: list[str] = Field(default_factory=list)
    missing_keywords: list[str] = Field(default_factory=list)
    grammar_suggestions: list[str] = Field(default_factory=list)
    formatting_suggestions: list[str] = Field(default_factory=list)
    improvement_recommendations: list[str] = Field(default_factory=list)


class ResumeSkillResponse(BaseModel):
    """Extracted skill returned in API responses."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    skill_name: str
    category: str
    proficiency_level: str | None = None


class ResumeAnalysisResponse(BaseModel):
    """Full API response for resume analysis and ATS evaluation."""

    model_config = ConfigDict(from_attributes=True)

    id: int
    resume_id: int
    resume_version_id: int
    user_id: int
    ats_score: float
    scoring_breakdown: dict
    experience_summary: str | None = None
    education_summary: str | None = None
    project_summary: str | None = None
    certifications: list[str] = Field(default_factory=list)
    strengths: list[str] = Field(default_factory=list)
    weaknesses: list[str] = Field(default_factory=list)
    missing_keywords: list[str] = Field(default_factory=list)
    grammar_suggestions: list[str] = Field(default_factory=list)
    formatting_suggestions: list[str] = Field(default_factory=list)
    improvement_recommendations: list[str] = Field(default_factory=list)
    skills: list[ResumeSkillResponse] = Field(default_factory=list)
    created_at: datetime
